// parseHexColor parses a hex color string and returns a color.Color.
// Supports 3, 4, 6, and 8 digit hex formats with or without '#' prefix.
func parseHexColor(hex string) (color.Color, error) {
	// Remove '#' prefix if present
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8

	switch len(hex) {
	case 3:
		// RGB: "abc" -> 0xaa 0xbb 0xcc 0xff
		fmt.Sscanf(hex, "%1x%1x%1x", &r, &g, &b)
		r = r*16 + r
		g = g*16 + g
		b = b*16 + b
		a = 0xff
	case 4:
		// RGBA: "abcd" -> 0xaa 0xbb 0xcc 0xdd
		fmt.Sscanf(hex, "%1x%1x%1x%1x", &r, &g, &b, &a)
		r = r*16 + r
		g = g*16 + g
		b = b*16 + b
		a = a*16 + a
	case 6:
		// RRGGBB: "a1b2c3" -> 0xa1 0xb2 0xc3 0xff
		fmt.Sscanf(hex, "%2x%2x%2x", &r, &g, &b)
		a = 0xff
	case 8:
		// RRGGBBAA: "a1b2c3f4" -> 0xa1 0xb2 0xc3 0xf4
		fmt.Sscanf(hex, "%2x%2x%2x%2x", &r, &g, &b, &a)
	default:
		return color.Transparent, fmt.Errorf("invalid hex color format: %s", hex)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// getColor retrieves a color from the JSON theme, checking variant-specific colors first
func (jt *jsonTheme) getColor(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	nameStr := string(name)

	// Check cache first
	cacheKey := nameStr + "-" + fmt.Sprint(variant)
	if c, ok := jt.parsedColors[cacheKey]; ok {
		return c
	}

	var hexColor string
	var found bool

	// Check variant-specific colors first
	if variant == fyne.VariantDark && jt.colorsDark != nil {
		hexColor, found = jt.colorsDark[nameStr]
	} else if variant == fyne.VariantLight && jt.colorsLight != nil {
		hexColor, found = jt.colorsLight[nameStr]
	}

	// Fall back to generic colors
	if !found && jt.colors != nil {
		hexColor, found = jt.colors[nameStr]
	}

	// If found, parse and cache
	if found {
		if c, err := parseHexColor(hexColor); err == nil {
			jt.parsedColors[cacheKey] = c
			return c
		}
	}

	// Fall back to base theme
	return jt.base.Color(name, variant)
}

