package binding

import (
	"fmt"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// sprintfBinding is a String binding that formats multiple source bindings using sprintf
type sprintfBinding struct {
	base
	format  string
	sources []DataItem
	lastErr error
}

// NewSprintf creates a formatted string binding that combines multiple source bindings.
// The format string follows fmt.Sprintf conventions. When any source binding changes,
// the formatted string is automatically updated.
//
// The returned binding supports Set() which uses fmt.Sscanf to parse the string back
// into the source bindings. Note that Bytes bindings cannot be round-tripped.
//
// Since: 2.2
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		return NewString()
	}

	sprintf := &sprintfBinding{
		format:  format,
		sources: b,
	}

	// Listen to all source bindings
	for _, source := range b {
		source.AddListener(NewDataListener(func() {
			sprintf.trigger()
		}))
	}

	return sprintf
}

// Get returns the formatted string by reading all source bindings and applying sprintf
func (s *sprintfBinding) Get() (string, error) {
	if s.lastErr != nil {
		return "", s.lastErr
	}

	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		val, err := getValue(source)
		if err != nil {
			s.lastErr = err
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(s.format, values...), nil
}

// Set parses the input string using fmt.Sscanf and updates all source bindings
func (s *sprintfBinding) Set(str string) error {
	if len(s.sources) == 0 {
		return nil
	}

	// Create pointers to hold parsed values
	ptrs := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		ptr, err := getPointerFor(source)
		if err != nil {
			return err
		}
		ptrs[i] = ptr
	}

	// Parse the string
	n, err := fmt.Sscanf(str, s.format, ptrs...)
	if err != nil && n == 0 {
		return err
	}

	// Set values back to source bindings
	for i, source := range s.sources {
		if err := setValue(source, ptrs[i]); err != nil {
			return err
		}
	}

	return nil
}

// trigger is called when any source binding changes
func (s *sprintfBinding) trigger() {
	s.lastErr = nil
	s.lock.RLock()
	listeners := s.listeners
	s.lock.RUnlock()

	for _, listener := range listeners {
		queueItem(listener.DataChanged)
	}
}

// getValue extracts the current value from a DataItem
func getValue(item DataItem) (interface{}, error) {
	switch v := item.(type) {
	case Bool:
		return v.Get()
	case Bytes:
		return v.Get()
	case Float:
		return v.Get()
	case Int:
		return v.Get()
	case Rune:
		return v.Get()
	case String:
		return v.Get()
	case URI:
		u, err := v.Get()
		if err != nil {
			return nil, err
		}
		return u.String(), nil
	default:
		return nil, fmt.Errorf("unsupported binding type")
	}
}

// getPointerFor creates a pointer to hold a parsed value for the given DataItem type
func getPointerFor(item DataItem) (interface{}, error) {
	switch item.(type) {
	case Bool:
		var v bool
		return &v, nil
	case Bytes:
		return nil, fmt.Errorf("Bytes bindings cannot be round-tripped through sprintf")
	case Float:
		var v float64
		return &v, nil
	case Int:
		var v int
		return &v, nil
	case Rune:
		var v rune
		return &v, nil
	case String:
		var v string
		return &v, nil
	case URI:
		var v string
		return &v, nil
	default:
		return nil, fmt.Errorf("unsupported binding type")
	}
}

// setValue updates a DataItem with a parsed value
func setValue(item DataItem, ptr interface{}) error {
	switch v := item.(type) {
	case Bool:
		return v.Set(*ptr.(*bool))
	case Float:
		return v.Set(*ptr.(*float64))
	case Int:
		return v.Set(*ptr.(*int))
	case Rune:
		return v.Set(*ptr.(*rune))
	case String:
		return v.Set(*ptr.(*string))
	case URI:
		uriStr := *ptr.(*string)
		u, err := storage.ParseURI(uriStr)
		if err != nil {
			return err
		}
		return v.Set(u)
	default:
		return fmt.Errorf("unsupported binding type for set")
	}
}

// StringToStringWithFormat creates a formatted String binding from a String binding.
// If the format is "%s", returns the original binding directly (no wrapping).
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

