// Menu stores the information required for a standard menu.
// A menu can pop down from a MainMenu or could be a pop out menu.
type Menu struct {
	Label string
	Items []*MenuItem
}

// Refresh triggers a redraw of this menu in all windows where it is currently displayed.
// This should be called after modifying menu items, icons, shortcuts, or other menu properties.
//
// Since: 2.2
func (m *Menu) Refresh() {
	// Implementation will be handled by the driver
	// This method exists to satisfy the API requirement
	for _, w := range CurrentApp().Driver().AllWindows() {
		if w.MainMenu() != nil {
			for _, menu := range w.MainMenu().Items {
				if menu == m {
					w.SetMainMenu(w.MainMenu())
					break
				}
			}
		}
	}
}

