// Package validation provides validation for data inside widgets
package validation

import (
	"errors"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a validator that ensures the input matches one of the provided valid strings.
// The validator returns nil if the input is in the list, otherwise returns an error.
//
// Since: 2.2
func NewAllStrings(valid []string) fyne.StringValidator {
	return func(input string) error {
		for _, v := range valid {
			if input == v {
				return nil
			}
		}
		return errors.New("input does not match any valid option")
	}
}

